 * @param[in] y: value of \c y component, default 0
 * @param[in] z: value of \c z component, default 0
 */
template <class T>
inline Point3<T>::Point3(T x, T y, T z) :
    xCoord(x),
    yCoord(y),
    zCoord(z)
{
}

template <class T>
Point3<T>::Point3(const Eigen::VectorXd& v) :
    xCoord(v(0)),
    yCoord(v(1)),
    zCoord(v(2))
{
}

